  'tool3-para2' => 'Գործարարները վստահում են Adobe Acrobat-ին փաստաթղթերի ճշգրտության և երկարաժամկետ կառավարման կարիքների համար: Բաժանորդագրության պլանները բացում են առաջադեմ գործիքները աշխատասեղանի և շարժական հարթակներում:',
  'tool3-pro1' => 'Adobe Acrobat-ը միշտ ապահովում է բարձր ճշգրտություն և դասավորության գերազանց պահպանում:',
  'tool3-pro2' => 'Անվտանգության առաջադեմ ընտրանքները պաշտպանում են զգայուն փաստաթղթերը գաղտնագրման գործիքներով:',
  'tool3-pro3' => 'Cross-platform աջակցությունը թույլ է տալիս անխափան օգտագործել սարքերի և օպերացիոն համակարգերի միջև:',
  'tool3-con1' => 'Բաժանորդագրության գինը թանկ է թվում պատահական կամ պատահական օգտվողների համար:',
  'tool3-con2' => 'Ինտերֆեյսի բարդությունը մարտահրավեր է նետում սկսնակներին օգտագործման վաղ փուլերում:',
  'tool3-con3' => 'Գործողությունը կարող է դանդաղել սահմանափակ ապարատային ռեսուրսներով հին սարքերում:',
  'comparison-intro' => 'Եկեք համառոտ համեմատենք վերը նշված գործիքները:',
  'table-header1' => 'Գործիքի անվանումը',
  'table-header2' => 'Արժեքի մոդել',
  'table-header3' => 'Պլատֆորմի աջակցություն',
  'table-header4' => 'Լավագույն օգտագործման դեպք',
  'table-row1-col1' => 'Smallpdf',
  'table-row1-col2' => 'Անվճար սահմանափակումներով և վճարովի պլաններով',
  'table-row1-col3' => 'Վեբ վրա հիմնված բոլոր սարքերում',
  'table-row1-col4' => 'Արագ առցանց պատկերի վերափոխում PDF',
  'table-row2-col1' => 'PDFgear',
  'table-row2-col2' => 'Լիովին անվճար',
  'table-row2-col3' => 'Windows և macOS աշխատասեղան',
  'table-row2-col4' => 'Անցանց պատկերների անսահմանափակ փոխարկումներ',
  'table-row3-col1' => 'Adobe Acrobat',
  'table-row3-col2' => 'Վճարովի բաժանորդագրություն',
  'table-row3-col3' => 'Սեղանի և շարժական հարթակներ',
  'table-row3-col4' => 'Պրոֆեսիոնալ փաստաթղթերի կառավարման կարիքներ',
  'layout-options-heading' => 'Պատկերի դասավորության ընտրանքներ',
  'layout-options-intro' => 'Պատկերները PDF-ի փոխարկելիս ահա այն, ինչ դուք պետք է իմանաք պատկերների դասավորության ընտրանքների մասին:',
  'layout1-heading' => 'Դիմանկարի դասավորություն',
  'layout1-para' => 'Դիմանկարի դասավորությունը համապատասխանում է այն փաստաթղթերին, որոնք պահանջում են ուղղահայաց ընթերցում, ինչպիսիք են հաշվետվությունները: Պատկերից դեպի PDF գործիքները պատկերները տեղադրում են ուղղահայաց և պահպանում դիտման բնական հոսքը: Այս դասավորությունը աջակցում է ստանդարտ տպագրությանը և բարելավում է ընթեռնելիությունը թվային էկրաններում:',
  'layout2-heading' => 'Լանդշաֆտի դասավորություն',
  'layout2-para' => 'Լանդշաֆտի դասավորությունը լավ է աշխատում լայն պատկերների համար, ինչպիսիք են գծապատկերները և ներկայացման սլայդները: Փոխակերպման գործիքները պտտում են պատկերները և հարթեցնում բովանդակությունը հորիզոնական PDF էջերում: Այս տարբերակը կանխում է պատկերի կտրումը և արդյունավետորեն պահպանում տեսողական հավասարակշռությունը:',
  'layout3-heading' => 'Լուսանցքի կարգավորումներ',
  'layout3-para' => 'Լուսանցքի կարգավորումները վերահսկում են պատկերի եզրերի և PDF էջի եզրագծերի միջև հեռավորությունը: Պատշաճ լուսանցքները բարելավում են փաստաթղթի տեսքը և թույլ չեն տալիս բովանդակությունը դիպչել եզրերին: Պատկերից դեպի PDF գործիքները թույլ են տալիս օգտվողներին հարմարեցնել լուսանցքները՝ հիմնվելով թողարկման կարիքների վրա:',
  'layout4-heading' => 'Պատկերի մասշտաբավորում',
  'layout4-para' => 'Պատկերի մասշտաբումը կարգավորում է պատկերի չափը՝ չվնասելով պարզությանը կամ հստակությանը: Սանդղակի ընտրանքները օգնում են մեծ պատկերները ճիշտ տեղավորվել ընտրված էջի դասավորությունների մեջ: Հավասարակշռված մասշտաբը ապահովում է պրոֆեսիոնալ արդյունքներ պատկերը PDF փոխակերպման ժամանակ:',
  'conclusion-heading' => 'Եզրակացություն',
  'conclusion-para1' => 'Պատկերի PDF փոխարկումը բարելավում է փաստաթղթերի փոխանակումը սարքերում և աշխատավայրերում: PDF ֆայլերը ավելի լավ են պահպանում կարգի հստակությունն ու համատեղելիությունը, քան առանձին պատկերային ֆայլերը: Պրոֆեսիոնալները, ուսանողները և ստեղծողները արդյունավետություն են ձեռք բերում ֆայլերի կազմակերպված կառավարման միջոցով:',
  'conclusion-para2' => 'Փոխակերպման գործիքները մշակում են վերբեռնված պատկերները, սահմանում էջի դասավորությունը և պահպանում տեսողական որակը: Օգտագործողները կարող են հարմարեցնել կողմնորոշման լուսանցքները և մասշտաբը մինչև PDF վերջնական ստեղծումը: Արդյունքը բացվում է հետևողականորեն և աջակցում է համօգտագործմանը, տպագրությանը և երկարաժամկետ պահպանմանը:',
  'conclusion-para3' => 'Առցանց գործիքները, ինչպիսիք են Smallpdf-ը, PDFgear-ը և Adobe Acrobat-ը, սպասարկում են տարբեր կարիքներ: Յուրաքանչյուր տարբերակ հավասարակշռում է ծախսերի առանձնահատկությունները և պլատֆորմի աջակցությունը օգտվողների համար:',
  'faqs-heading' => 'ՀՏՀ-ներ',
  'faq1-question' => 'Պատկերի ո՞ր ձևաչափերն են աջակցվում:',
  'faq1-answer' => 'Պատկերից դեպի PDF գործիքների մեծ մասն աջակցում է JPG, PNG, BMP և TIFF ձևաչափերին: Այս ձևաչափերը ներառում են ընդհանուր սարքերի լուսանկարները, սկանավորումները և գրաֆիկան: Օգտագործողները վերբեռնում են պատկերներ տեսախցիկներից, հեռախոսներից և սկաներներից՝ առանց ձևաչափի խնդիրների: Հանրաճանաչ ձևաչափերի աջակցությունը ապահովում է սահուն փոխակերպում տարբեր աշխատանքային հոսքերում:',
  'faq2-question' => 'Կարո՞ղ եմ վերադասավորել նկարները:',
  'faq2-answer' => 'Պատկերից դեպի PDF գործիքները թույլ են տալիս հեշտությամբ վերադասավորել պատկերները մինչև վերջնական ֆայլի ստեղծումը: Օգտատերերը նկարները քաշում են նախընտրած հաջորդականության մեջ՝ նախադիտման էկրաններում: Ճիշտ կարգը զգալիորեն բարելավում է փաստաթղթերի հոսքը և ընթերցանության փորձը: Վերադասավորման գործառույթներն օգնում են օգտվողներին խուսափել սխալներից փաստաթղթերի պատրաստման ժամանակ:',
  'faq3-question' => 'Արդյո՞ք պատկերը PDF-ի համար անվճար է:',
  'faq3-answer' => 'Պատկերից դեպի PDF շատ գործիքներ առաջարկում են անվճար փոխակերպում հիմնական հատկանիշներով: Անվճար տարբերակները հաճախ ներառում են ֆայլի չափի կամ օգտագործման հաճախականության սահմանափակումներ: Որոշ հարթակներ պահանջում են վճարում առաջադեմ խմբագրման կամ անսահմանափակ մուտքի համար: Օգտագործողները պետք է վերանայեն գործիքի սահմանաչափերը՝ նախքան անվճար տարբերակ ընտրելը:',
  'faq4-question' => 'PDF-ը պահպանում է պատկերի որակը:',
  'faq4-answer' => 'PDF ֆայլերը պահպանում են պատկերի որակը, երբ գործիքներն օգտագործում են համապատասխան սեղմման կարգավորումներ: Բարձր լուծաչափով պատկերները պահպանում են պարզություն փաստաթղթերի պրոֆեսիոնալ փոխանակման ընթացքում: Որակի կարգավորումները թույլ են տալիս հավասարակշռություն պահպանել ֆայլի չափի և տեսողական հստակության միջև: Հուսալի գործիքները պաշտպանում են պատկերի մանրամասները փոխակերպման գործընթացում:',
  'faq5-question' => 'Կարո՞ղ եմ պատկերները փոխարկել բջջայինով:',
  'faq5-answer' => 'Պատկերի PDF փոխարկումը լավ է աշխատում շարժական սարքերում բրաուզերների միջոցով: Շատ գործիքներ աջակցում են Android և iOS համակարգերին՝ առանց լրացուցիչ ծրագրերի: Բջջային փոխակերպումն օգնում է օգտատերերին կառավարել փաստաթղթերը ճանապարհորդելիս կամ հեռակա աշխատելիս: Ամպի վրա հիմնված գործիքներն ապահովում են հարթ մուտք հեռախոսների և պլանշետների միջև:',
);
